 if(v.op==='start')return Object.keys(v).every(k=>['op','actionId','expectedRevision','difficulty','stake'].includes(k))&&['easy','normal','hard'].includes(v.difficulty)&&(!Object.hasOwn(v,'stake')||[0,100].includes(v.stake));
