 if(!ballots(g.ballots)||!(g.eliminated===null||seat(g.eliminated))||g.votes!==null&&(!obj(g.votes)||Object.keys(g.votes).some(k=>!seat(Number(k))||!Number.isInteger(g.votes[k])||g.votes[k]<0||g.votes[k]>7)))fail();
 if(!Array.isArray(g.voteHistory)||g.voteHistory.length>25||g.voteHistory.some(r=>!obj(r)||!Number.isInteger(r.round)||r.round<1||r.round>g.round||!ballots(r.ballots)||!(r.eliminated===null||seat(r.eliminated))||!string(r.message)))fail();
