 const l=g.legal;if(!obj(l)||!Array.isArray(l.actions)||new Set(l.actions).size!==l.actions.length||l.actions.some(a=>!ACTIONS.includes(a))||!Array.isArray(l.targets)||new Set(l.targets).size!==l.targets.length||l.targets.some(i=>!seat(i)||!g.players[i].alive)||!Array.isArray(l.marks)||new Set(l.marks).size!==l.marks.length||l.marks.some(i=>!seat(i)||i===0))fail();
 if(g.over&&(l.actions.length||l.targets.length||l.marks.length)||g.phase==='vote'&&l.targets.includes(0)||g.phase==='night'&&me.role==='mafia'&&l.targets.some(i=>g.players[i].role==='mafia')||!g.over&&(g.winningTeam!==null||g.win||g.draw||g.resigned))fail();
 const e=g.economy,outcome=!g.over?null:g.resigned?'resigned':g.draw?'draw':g.win?'win':'loss';
 if(!obj(e)||Object.keys(e).length!==6||e.version!==1||![0,100].includes(e.stake)||e.settled!==g.over||e.outcome!==outcome||e.payout!==(e.stake?({win:250,draw:100}[outcome]||0):0)||e.xp!==(e.stake?({win:130,loss:25,draw:40}[outcome]||0):0))fail();
