function factsMarkup(g){const f=g.voteFacts;if(!f||!f.total)return '';return `<details class="sm-history" data-keep="facts"><summary>Разбор твоих голосов <span>${f.total}</span></summary><p>Против мафии: ${f.againstMafia}. Против города: ${f.againstTown}. Один голос сам по себе не определяет исход всей партии.</p><ul class="sm-facts">${f.rows.map(r=>`<li><span>День ${r.round}</span><b>${esc(r.name)}</b><em>${esc(ROLE[r.role].label)}</em></li>`).join('')}</ul></details>`;}
