function setupMarkup(over=false){return `<section class="sm-setup" id="sm-new-game"><div class="sm-setup-copy"><span class="sm-eyebrow">МАФИЯ / ГОРОД СЕКРЕТОВ</span><h1>${over?'Новая ночь.<br>Новая история.':'У каждого есть<br>что скрывать.'}</h1><p>Семь жителей садятся за один стол. Двое знают друг друга. Остальным предстоит понять, кому можно верить.</p><div class="sm-counts"><span><b>7</b>жителей</span><span><b>2</b>мафии</span><span><b>1</b>твоя роль</span></div><div class="sm-role-preview"><span>♠ Мафия</span><span>◇ Комиссар</span><span>✚ Доктор</span><span>○ Горожане</span></div></div><div class="sm-setup-form"><label>Сложность ботов<select id="sm-difficulty" ${!writable()?'disabled':''}>${[['easy','Знакомство с городом'],['normal','Внимательные соперники'],['hard','Опытные игроки']].map(([v,n])=>`<option value="${v}" ${setupDifficulty===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Режим партии<select id="sm-stake" aria-describedby="sm-stake-hint" ${!writable()?'disabled':''}><option value="0" ${setupStake===0?'selected':''}>Практика · бесплатно</option><option value="100" ${setupStake===100?'selected':''}>Игровые монеты · 100 V</option></select></label><p id="sm-stake-hint" data-stake-hint></p><button class="sm-button primary" data-start disabled>Получить роль · бесплатно</button><small>Против шести ботов. Монеты не имеют денежной стоимости.</small></div></section>`;}
function roleMarkup(g){const me=g.players[0],r=ROLE[me.role];return `<section class="sm-role-card"><span class="sm-role-symbol" aria-hidden="true">${r.symbol}</span><div><span class="sm-eyebrow">ТВОЯ РОЛЬ · ${!me.alive?'НАБЛЮДЕНИЕ':'ЛИЧНАЯ КАРТОЧКА'}</span><h2>${r.label}</h2><p>${esc(r.goal)}${!me.alive&&!g.over?' Ты выбыл, но можешь наблюдать и дождаться результата своей стороны.':''}</p></div><span class="sm-role-team">${me.role==='mafia'?'Сторона мафии':'Сторона города'}</span></section>`;}
