 const event=phase==='dawn'?`<section class="sm-event"><span class="sm-eyebrow">РАССВЕТ / ДЕНЬ ${g.round}</span><h2 data-step-title>Что произошло ночью</h2><p>${esc(g.nightText)}</p></section>`:phase==='voteResult'?voteResultMarkup(g):'';
 app.innerHTML=header+sync+notice+`<div class="sm-heading"><div><span class="sm-eyebrow">${g.economy.stake?'ВХОД 100 V · ИГРОВЫЕ МОНЕТЫ':'БЕСПЛАТНАЯ ПРАКТИКА'}</span><h1>Город секретов</h1></div><div class="sm-round"><b>${String(g.round).padStart(2,'0')}</b><span>${phaseLabel[phase]}</span></div></div>`+(g.over?outcomeMarkup(g)+finalEventMarkup(g):timelineMarkup(g))+roleMarkup(g)+`<div class="sm-play ${g.over?'finished':''}"><div class="sm-main">${event}${notebookMarkup(g)}${phase==='day'?statementsMarkup(g):''}${roster}${phase!=='day'&&g.statements.length?`<details class="sm-history" data-keep="versions"><summary>Версии жителей</summary>${statementsMarkup(g)}</details>`:''}</div>${g.over?'':commandMarkup(g)}</div>`+(g.over?factsMarkup(g)+setupMarkup(true):'')+`<div class="sm-bottom">${g.voteHistory.length?`<details class="sm-history" data-keep="history"><summary>История голосований <span>${g.voteHistory.length}</span></summary>${[...g.voteHistory].reverse().map(r=>voteResultMarkup(g,r)).join('')}</details>`:''}<details class="sm-history" data-keep="log"><summary>Хроника города</summary><ul class="sm-log">${g.log.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details>${rulesMarkup()}${g.legal.actions.includes('resign')?'<button class="sm-link subtle" data-resign>Завершить партию досрочно</button><div data-resign-host></div>':''}<footer class="sm-footer"><p>Дождись статуса «Выбор сохранён», затем войди в тот же аккаунт на другом устройстве.</p><a class="sm-link" href="./index.html?view=lobby">Все игры →</a></footer></div>`;
