 bind();if(markFocus!==null&&writable()){const mark=$('[data-mark="'+markFocus+'"]');if(mark)mark.focus({preventScroll:true});markFocus=null;}const transition=g.id+'|'+g.phase+'|'+g.round;if(lastViewKey&&lastViewKey!==transition){const target=$('[data-step-title]');if(target){target.setAttribute('tabindex','-1');target.focus({preventScroll:true});target.scrollIntoView({block:'start',behavior:'auto'});}}lastViewKey=transition;
